const TOPICS=[
 {id:'hist',ch:1,name:'Co to jest historia',hint:'Historia to przeszłość, opowieść o niej i nauka o przeszłości. Historycy badają ludzi, którzy żyli naprawdę, i wydarzenia, do których naprawdę doszło, a najważniejsza jest dla nich prawda. W baśniach bohaterowie i zdarzenia są wymyślone, w legendach prawda miesza się z nieprawdą. Historia pomaga zrozumieć świat i przewidywać skutki działań.'},
 {id:'zrodla',ch:1,name:'Rodzaje źródeł historycznych',hint:'Źródłem jest każdy ślad działalności człowieka. Materialne pisane: książki, kroniki, dokumenty, listy, gazety, mapy. Materialne niepisane: budowle, obrazy, rzeźby, odzież, zdjęcia, przedmioty. Niematerialne: tradycja, obyczaje, przekazy ustne. Archeolodzy szukają materialnych śladów na wykopaliskach.'},
 {id:'wiary',ch:1,name:'Wiarygodność źródeł i praca historyka',hint:'Wiarygodność źródła to na ile zawarte w nim informacje są pewne. Historyk ustala, kto, kiedy i w jakim celu je stworzył, porównuje je z innymi źródłami i ustaleniami archeologów. Fakt można sprawdzić, a opinia to czyjś pogląd.'},
 {id:'przyczyny',ch:1,name:'Przyczyny i skutki',hint:'Przyczyny: dlaczego do czegoś doszło. Skutki: co z tego wynikło. Związki przyczynowo-skutkowe to zależności między wydarzeniami, w których jedno prowadziło do drugiego (np. wynalezienie druku przez Gutenberga).'},
 {id:'rodzina',ch:2,name:'Jak poznać historię rodziny',hint:'Źródła wiedzy o rodzinie: opowieści krewnych i pamiątki rodzinne (zdjęcia, dokumenty, listy, przedmioty codziennego użytku). Krewni mają wspólnego przodka.'},
 {id:'drzewo',ch:2,name:'Drzewo genealogiczne',hint:'Najstarsi przodkowie są na dole (pień), najmłodsi na górze. Obrączki łączą małżonków. Genealogia bada historię rodziny.'},
 {id:'tradycje',ch:2,name:'Tradycje rodzinne',hint:'Tradycja to zwyczaje, wspólny zawód, zamiłowania, przepisy. Wzmacnia więzi i pozwala utrzymać bliski kontakt.'},
 {id:'chrono',ch:3,name:'Chronologia i oś czasu',hint:'Chronologia to nauka o mierzeniu czasu. Porządek chronologiczny: od najdawniejszego do najnowszego. Na osi czasu najstarsze po lewej, najnowsze po prawej.'},
 {id:'jedn',ch:3,name:'Jednostki czasu',hint:'Rok = 365 lub 366 dni, wiek (stulecie) = 100 lat, tysiąclecie = 1000 lat = 10 wieków.'},
 {id:'ery',ch:3,name:'Ery i prehistoria',hint:'Nasza era (n.e.) liczy się od narodzin Jezusa z Nazaretu, wcześniejsze czasy to p.n.e. Nie było roku zerowego. Historia zaczyna się od wynalezienia pisma, wcześniej była prehistoria.'},
 {id:'epoki',ch:3,name:'Epoki historyczne',hint:'Starożytność (ok. 3400 p.n.e. – 476), średniowiecze (476 – 1492), nowożytność (1492 – 1918), współczesność (od 1918).'},
 {id:'rzym',ch:3,name:'Liczby rzymskie',hint:'I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000. Mniejsza cyfra przed większą się odejmuje (IV = 4, IX = 9, XL = 40).'},
 {id:'oblicz',ch:4,name:'Obliczanie upływu lat',hint:'Ta sama era n.e.: późniejsza − wcześniejsza. P.n.e.: wcześniejsza (większa) − późniejsza (mniejsza). Różne ery: dodaj obie daty i odejmij 1.'},
 {id:'wiek',ch:4,name:'Który to wiek',hint:'Odrzuć dwie ostatnie cyfry i dodaj 1 (1410 → 14 + 1 → XV wiek). Jeśli rok kończy się dwoma zerami, nie dodajesz 1 (1400 → XIV wiek). Dotyczy też p.n.e.'},
 {id:'zegary',ch:5,name:'Jak dawniej mierzono czas',hint:'Słońce i cień (zegar słoneczny), klepsydra z piaskiem, zegary mechaniczne ze średniowiecza (ciężarki, koła zębate, dzwony), zegarki kieszonkowe, na rękę, cyfrowe.'},
 {id:'kal',ch:5,name:'Kalendarz',hint:'Księżycowy (ok. 29 dni, 12 miesięcy) → egipski (365 dni) → juliański (Juliusz Cezar, 29 lutego co 4 lata) → gregoriański (Grzegorz XIII, 1582, pominięto 10 dni).'}
];
