/* ---------- drzewo genealogiczne ---------- */
const treeHTML=(rows,desc)=>`<div class="tree">${rows.map((r,i)=>`<div class="tr">${i===0?'<span class="tl">góra – najmłodsi</span>':''}${i===rows.length-1?'<span class="tl">dół – najstarsi</span>':''}${r.map(b=>`<span class="tb">${b}</span>`).join('')}</div>`).join('')}<p class="tdesc">${desc}</p></div>`;
const FEM=['Anna','Joanna','Kasia','Teresa','Helena','Zofia','Maria','Ewa','Halina','Irena','Jadwiga','Ola','Danuta','Krystyna'];
const MAS=['Tomasz','Piotr','Stefan','Zbigniew','Jan','Kuba','Marek','Adam','Henryk','Paweł','Ryszard','Andrzej','Józef','Leon'];
function fam(){const f=pickN(FEM,5),m=pickN(MAS,5);return{sis:f[0],mama:f[1],bab:f[2],sb:f[3],pb:f[4],bro:m[0],tata:m[1],stryj:m[2],dz:m[3],pd:m[4]}}
const famHTML=p=>treeHTML([[p.sis,'Ja',p.bro],[`${p.mama} 💍 ${p.tata}`,p.stryj],[p.sb,`${p.bab} 💍 ${p.dz}`],[`${p.pb} 💍 ${p.pd}`]],
  `💍 = małżeństwo. ${p.pb} i ${p.pd} mają córki: ${p.sb} i ${p.bab}. ${p.bab} i ${p.dz} mają synów: ${p.tata} i ${p.stryj}. ${p.tata} i ${p.mama} mają dzieci: ${p.sis}, Ja i ${p.bro}.`);
const ROLES_JA=['siostra','brat','mama','tata','stryj (brat taty)','babcia','dziadek','siostra babci','prababcia','pradziadek'];
const ROLES_TATA=['mama','tata','brat','ciocia (siostra mamy)','babcia','dziadek','żona','syn'];
function famRole(l){return D(l,()=>{const p=fam();
  if(l===3){const c=[['bab','mama'],['dz','tata'],['stryj','brat'],['sb','ciocia (siostra mamy)'],['pb','babcia'],['pd','dziadek']],x=P(c);
    return{q:famHTML(p)+`<br>Kim jest <b>${p[x[0]]}</b> dla osoby o imieniu <b>${p.tata}</b>?`,ok:x[1],bad:pickN(ROLES_TATA.filter(r=>r!==x[1]),3),expl:`${p[x[0]]} to ${x[1]} dla osoby ${p.tata}. ${p.tata} jest synem ${p.bab} i ${p.dz}, więc jego rodzicami są oni, a siostra jego mamy to ciocia.`}}
  const pool=l===1?[['sis','siostra'],['bro','brat'],['mama','mama'],['tata','tata'],['bab','babcia'],['dz','dziadek']]:[['stryj','stryj (brat taty)'],['pb','prababcia'],['pd','pradziadek'],['sb','siostra babci'],['bab','babcia'],['dz','dziadek']];
  const x=P(pool);return{q:famHTML(p)+`<br>Kim jest <b>${p[x[0]]}</b> dla osoby „Ja”?`,ok:x[1],bad:pickN(ROLES_JA.filter(r=>r!==x[1]),3),expl:`${p[x[0]]} to ${x[1]} osoby „Ja”. Czytaj drzewo od dołu: starsze pokolenia mają dzieci poziom wyżej.`}})}

